using UniversityCourseCatalog.Models;

namespace UniversityCourseCatalog.Services;

public class CatalogService
{
    private readonly List<Department> _departments =
    [
        new() { Id = 1, Name = "Computer Science", Abbreviation = "CS" },
        new() { Id = 2, Name = "Mathematics", Abbreviation = "MATH" },
        new() { Id = 3, Name = "English", Abbreviation = "ENG" },
        new() { Id = 4, Name = "Physics", Abbreviation = "PHYS" },
        new() { Id = 5, Name = "History", Abbreviation = "HIST" },
    ];

    private readonly List<Course> _courses;

    public CatalogService()
    {
        _courses =
        [
            new()
            {
                Id = 1, CourseCode = "CS 101", Title = "Introduction to Programming",
                Description = "An introductory course covering fundamental programming concepts using Python. Topics include variables, control flow, functions, and basic data structures.",
                Credits = 3, Schedule = "Mon/Wed/Fri 9:00–9:50 AM", DepartmentId = 1, DepartmentName = "Computer Science",
                InstructorName = "Dr. Sarah Chen", InstructorBio = "Dr. Chen has 15 years of experience in software engineering and computer science education. She holds a Ph.D. from MIT and has published extensively on programming pedagogy.",
                IsFeatured = true
            },
            new()
            {
                Id = 2, CourseCode = "CS 301", Title = "Data Structures and Algorithms",
                Description = "Advanced study of data structures including trees, graphs, and hash tables. Covers algorithm design, complexity analysis, and problem-solving strategies.",
                Credits = 4, Schedule = "Tue/Thu 10:30–11:45 AM", DepartmentId = 1, DepartmentName = "Computer Science",
                InstructorName = "Dr. James Rodriguez", InstructorBio = "Dr. Rodriguez is an ACM Distinguished Educator with research interests in algorithm optimization and competitive programming.",
                IsFeatured = false
            },
            new()
            {
                Id = 3, CourseCode = "CS 450", Title = "Machine Learning",
                Description = "Foundations of machine learning including supervised and unsupervised learning, neural networks, and model evaluation. Includes hands-on projects with real-world datasets.",
                Credits = 4, Schedule = "Mon/Wed 2:00–3:15 PM", DepartmentId = 1, DepartmentName = "Computer Science",
                InstructorName = "Dr. Aisha Patel", InstructorBio = "Dr. Patel is a former Google AI researcher who joined academia to advance ML education. Her work on explainable AI has been cited over 3,000 times.",
                IsFeatured = true
            },
            new()
            {
                Id = 4, CourseCode = "MATH 201", Title = "Calculus II",
                Description = "Continuation of single-variable calculus covering techniques of integration, infinite series, parametric equations, and polar coordinates.",
                Credits = 4, Schedule = "Mon/Wed/Fri 11:00–11:50 AM", DepartmentId = 2, DepartmentName = "Mathematics",
                InstructorName = "Prof. Michael Torres", InstructorBio = "Prof. Torres is an award-winning mathematics educator with 20 years of teaching experience and a passion for making calculus accessible to all students.",
                IsFeatured = false
            },
            new()
            {
                Id = 5, CourseCode = "MATH 310", Title = "Linear Algebra",
                Description = "Study of vector spaces, linear transformations, matrices, determinants, eigenvalues, and applications to systems of equations.",
                Credits = 3, Schedule = "Tue/Thu 1:00–2:15 PM", DepartmentId = 2, DepartmentName = "Mathematics",
                InstructorName = "Dr. Elena Volkov", InstructorBio = "Dr. Volkov specializes in applied linear algebra and numerical methods. She has authored two widely adopted textbooks in the field.",
                IsFeatured = true
            },
            new()
            {
                Id = 6, CourseCode = "ENG 102", Title = "Composition and Rhetoric",
                Description = "Develops skills in academic writing, argumentation, and critical analysis of texts. Students produce multiple essays and a research paper.",
                Credits = 3, Schedule = "Mon/Wed 10:00–10:50 AM", DepartmentId = 3, DepartmentName = "English",
                InstructorName = "Prof. David Kim", InstructorBio = "Prof. Kim is a published author and writing instructor whose students have gone on to careers in journalism, publishing, and academia.",
                IsFeatured = false
            },
            new()
            {
                Id = 7, CourseCode = "ENG 340", Title = "American Literature: 1900–Present",
                Description = "Survey of major American literary works from the 20th and 21st centuries, examining themes of identity, modernity, and social change.",
                Credits = 3, Schedule = "Tue/Thu 3:00–4:15 PM", DepartmentId = 3, DepartmentName = "English",
                InstructorName = "Dr. Maria Gonzalez", InstructorBio = "Dr. Gonzalez is a Pulitzer Prize-nominated literary critic specializing in contemporary American fiction and multicultural narratives.",
                IsFeatured = false
            },
            new()
            {
                Id = 8, CourseCode = "PHYS 201", Title = "General Physics I",
                Description = "Introductory physics covering mechanics, thermodynamics, and waves. Includes weekly laboratory sessions with hands-on experiments.",
                Credits = 4, Schedule = "Mon/Wed/Fri 1:00–1:50 PM + Thu Lab 2:00–4:50 PM", DepartmentId = 4, DepartmentName = "Physics",
                InstructorName = "Dr. Robert Nakamura", InstructorBio = "Dr. Nakamura is a former NASA physicist who brings real-world applications into the classroom. He has received multiple teaching excellence awards.",
                IsFeatured = true
            },
            new()
            {
                Id = 9, CourseCode = "HIST 101", Title = "World Civilizations I",
                Description = "Survey of world history from ancient civilizations through the Renaissance, focusing on cultural exchange, political systems, and technological development.",
                Credits = 3, Schedule = "Tue/Thu 9:00–10:15 AM", DepartmentId = 5, DepartmentName = "History",
                InstructorName = "Prof. Angela Wright", InstructorBio = "Prof. Wright is an archaeologist and historian who has led excavations in three continents. She brings artifacts and primary sources into every lecture.",
                IsFeatured = false
            },
            new()
            {
                Id = 10, CourseCode = "HIST 315", Title = "The Civil Rights Movement",
                Description = "In-depth examination of the American civil rights movement from 1954–1975, drawing on primary documents, oral histories, and film.",
                Credits = 3, Schedule = "Mon/Wed 3:30–4:45 PM", DepartmentId = 5, DepartmentName = "History",
                InstructorName = "Dr. Marcus Johnson", InstructorBio = "Dr. Johnson is a civil rights historian whose oral history archive contains over 200 interviews with movement participants.",
                IsFeatured = false
            },
        ];
    }

    public List<Department> GetDepartments() => _departments;

    public Department? GetDepartment(int id) => _departments.FirstOrDefault(d => d.Id == id);

    public List<Course> GetCourses(string? searchTerm = null, int? departmentId = null)
    {
        var query = _courses.AsEnumerable();

        if (departmentId.HasValue)
        {
            query = query.Where(c => c.DepartmentId == departmentId.Value);
        }

        if (!string.IsNullOrWhiteSpace(searchTerm))
        {
            var term = searchTerm.Trim();
            query = query.Where(c =>
                c.Title.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.CourseCode.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.InstructorName.Contains(term, StringComparison.OrdinalIgnoreCase));
        }

        return query.ToList();
    }

    public Course? GetCourse(int id) => _courses.FirstOrDefault(c => c.Id == id);

    public List<Course> GetFeaturedCourses() => _courses.Where(c => c.IsFeatured).ToList();
}

